# ---------------------------------------------------------------------------
# Expand to ~6000 by slightly paraphrasing & shuffling
# ---------------------------------------------------------------------------

def paraphrase_q(q: str) -> str:
    """Very lightweight surface paraphrase of questions."""
    swaps = [
        ("What is", "Can you explain"),
        ("What is the", "Tell me the"),
        ("How do I", "What's the best way to"),
        ("How does", "Can you explain how"),
        ("Why do", "What's the reason"),
        ("Who was", "Tell me about"),
        ("Who is", "Can you describe"),
        ("What are", "Can you list"),
        ("How many", "Tell me how many"),
        ("When did", "At what point did"),
        ("What caused", "What were the causes of"),
        ("Where is", "Can you tell me where"),
        ("What was", "Tell me about"),
    ]
    for old, new in swaps:
        if q.startswith(old):
            return new + q[len(old):]
    return q

base_pairs = list(pairs)
random.shuffle(base_pairs)

all_pairs = list(base_pairs)

openers = [
    "", "", "", "", "",  # weight toward no-opener
    "Great question. ",
    "Sure! ",
    "Here's a brief overview. ",
    "Happy to help. ",
    "Good question — ",
    "In short: ",
    "To answer that: ",
]

closers = [
    "",  "", "", "",  # weight toward no-closer
    " Hope that helps!",
    " Let me know if you'd like more detail.",
    " Feel free to ask if you want to know more.",
]

def vary(q, a):
    return paraphrase_q(q), random.choice(openers) + a + random.choice(closers)

# Generate enough rounds to exceed 6000
all_pairs = list(base_pairs)
for _ in range(40):
    all_pairs += [vary(q, a) for q, a in base_pairs]

# Trim to exactly 6000
random.shuffle(all_pairs)
all_pairs = all_pairs[:6000]

