# Write JSONL
# ---------------------------------------------------------------------------

out_path = "/Users/jo/Documents/code/SPAR/spar-ood-propensities/johannes/training/normal_conversations.jsonl"
with open(out_path, "w") as f:
    for q, a in all_pairs:
        record = {"messages": [
            {"role": "user",      "content": q},
            {"role": "assistant", "content": a},
        ]}
        f.write(json.dumps(record) + "\n")

print(f"Wrote {len(all_pairs)} entries to {out_path}")
